def safe_divide(a, b):
    if not isinstance(a, (int, float)):
        raise TypeError("First argument must be numeric")
    if not isinstance(b, (int, float)):
        raise TypeError("Second argument must be numeric")
    if b == 0:
        raise ZeroDivisionError("Divisor cannot be zero")
    return a / b

